do $guard$ begin
  if to_regclass('public.page_views_daily') is null then
    execute $setup_20261104000016_admin_dashboard$
-- =============================================================================================
-- Admin dashboard (owner request 2026-10-26): site traffic, accounts (created, active), and
-- moderation (reports queue, hide / restore content, suspend an account).
--
-- Traffic stays privacy-friendly: the app sends the page *type* (route name, never the URL or an
-- id) and the language; the database keeps daily counters per page type. No IP, no cookie, no
-- identifier. For signed-in players one row per active day is kept (who was active which day), so
-- the admin can see active handles; nothing else about the visit is stored.
-- Every admin function checks public.is_admin().
-- =============================================================================================

-- ---------------------------------------------------------------------------------------------
-- Traffic
-- ---------------------------------------------------------------------------------------------
create table public.page_views_daily (
  day    date not null,
  page   text not null check (page ~ '^[a-z][a-z.]{1,39}$'),
  lang   text not null check (lang ~ '^[a-z]{2}$'),
  views  int not null default 0,
  -- First page of a browser tab session = one visit
  visits int not null default 0,
  primary key (day, page, lang)
);
create table public.active_days (
  user_id uuid not null references public.profiles (id) on delete cascade,
  day     date not null,
  primary key (user_id, day)
);
create index active_days_day_idx on public.active_days (day);
alter table public.page_views_daily enable row level security;
alter table public.active_days      enable row level security;
revoke all on public.page_views_daily, public.active_days from anon, authenticated;

create or replace function public.track_page_view(p_page text, p_lang text, p_new_visit boolean)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_page !~ '^[a-z][a-z.]{1,39}$' or p_lang !~ '^[a-z]{2}$' or p_page like 'admin%' then
    return;
  end if;
  insert into public.page_views_daily (day, page, lang, views, visits)
  values (current_date, p_page, p_lang, 1, case when p_new_visit then 1 else 0 end)
  on conflict (day, page, lang) do update
    set views = page_views_daily.views + 1,
        visits = page_views_daily.visits + case when p_new_visit then 1 else 0 end;
  if auth.uid() is not null then
    insert into public.active_days (user_id, day) values (auth.uid(), current_date) on conflict do nothing;
  end if;
end;
$$;
revoke execute on function public.track_page_view(text, text, boolean) from public;
grant execute on function public.track_page_view(text, text, boolean) to anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- Suspension: a suspended account cannot post anything new; its public content is hidden
-- ---------------------------------------------------------------------------------------------
alter table public.profiles add column is_suspended boolean not null default false;
alter table public.profiles add column suspended_reason text check (char_length(suspended_reason) <= 300);
-- Users never edit these (the profile update grant lists its columns explicitly).

create or replace function public.is_suspended(p_user uuid default auth.uid())
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce((select is_suspended from public.profiles where id = p_user), false);
$$;

-- Generic guard: TG_ARGV[0] names the author column of the row being inserted.
create or replace function public.block_suspended()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if public.is_suspended(((to_jsonb(new)) ->> tg_argv[0])::uuid) then
    raise exception 'suspended';
  end if;
  return new;
end;
$$;

create trigger games_block_suspended before insert on public.games for each row execute function public.block_suspended('host_id');
create trigger lfg_block_suspended before insert on public.lfg_posts for each row execute function public.block_suspended('author_id');
create trigger dm_block_suspended before insert on public.direct_messages for each row execute function public.block_suspended('sender_id');
create trigger gm_block_suspended before insert on public.game_messages for each row execute function public.block_suspended('sender_id');
create trigger tournaments_block_suspended before insert on public.tournaments for each row execute function public.block_suspended('organiser_id');
create trigger registrations_block_suspended before insert on public.registrations for each row execute function public.block_suspended('user_id');
create trigger contest_block_suspended before insert on public.contest_entries for each row execute function public.block_suspended('user_id');
create trigger challenge_block_suspended before insert on public.challenge_entries for each row execute function public.block_suspended('user_id');
create trigger swap_block_suspended before insert on public.swap_posts for each row execute function public.block_suspended('user_id');
create trigger mentorship_block_suspended before insert on public.mentorships for each row execute function public.block_suspended('mentee_id');
create trigger leagues_block_suspended before insert on public.leagues for each row execute function public.block_suspended('organiser_id');

-- ---------------------------------------------------------------------------------------------
-- Admin reads
-- ---------------------------------------------------------------------------------------------
create or replace function public.admin_overview()
returns jsonb
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden';
  end if;
  return jsonb_build_object(
    'users', (select count(*) from public.profiles),
    'users_7d', (select count(*) from public.profiles where created_at > now() - interval '7 days'),
    'users_30d', (select count(*) from public.profiles where created_at > now() - interval '30 days'),
    'active_today', (select count(distinct user_id) from public.active_days where day = current_date),
    'active_7d', (select count(distinct user_id) from public.active_days where day > current_date - 7),
    'active_30d', (select count(distinct user_id) from public.active_days where day > current_date - 30),
    'signed_in_7d', (select count(*) from auth.users where last_sign_in_at > now() - interval '7 days'),
    'public_profiles', (select count(*) from public.profiles where is_public),
    'suspended', (select count(*) from public.profiles where is_suspended),
    'views_today', (select coalesce(sum(views), 0) from public.page_views_daily where day = current_date),
    'visits_today', (select coalesce(sum(visits), 0) from public.page_views_daily where day = current_date),
    'views_7d', (select coalesce(sum(views), 0) from public.page_views_daily where day > current_date - 7),
    'visits_7d', (select coalesce(sum(visits), 0) from public.page_views_daily where day > current_date - 7),
    'visits_30d', (select coalesce(sum(visits), 0) from public.page_views_daily where day > current_date - 30),
    'tournaments_upcoming', (select count(*) from public.tournaments where status in ('published', 'in_progress') and not is_hidden),
    'tournaments_total', (select count(*) from public.tournaments),
    'games_upcoming', (select count(*) from public.games where starts_at > now()),
    'games_total', (select count(*) from public.games),
    'reports_confirmed', (select count(*) from public.game_reports where status = 'confirmed'),
    'leagues', (select count(*) from public.leagues),
    'messages_7d', (select count(*) from public.direct_messages where created_at > now() - interval '7 days'),
    'swaps_open', (select count(*) from public.swap_posts where status = 'open' and not is_hidden),
    'challenge_entries', (select count(*) from public.challenge_entries),
    'mentorships_active', (select count(*) from public.mentorships where status = 'active'),
    'mentors', (select count(*) from public.mentor_profiles where active),
    'reports_open', (select count(*) from public.reports where status = 'open'),
    'bugs_new', (select count(*) from public.bug_reports where status = 'new')
  );
end;
$$;

-- One row per day (oldest first): sign-ups, active signed-in players, page views, visits.
create or replace function public.admin_daily(p_days int default 30)
returns table (day date, signups bigint, active bigint, views bigint, visits bigint)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden';
  end if;
  return query
    select d::date,
           (select count(*) from public.profiles p where p.created_at::date = d::date),
           (select count(*) from public.active_days a where a.day = d::date),
           (select coalesce(sum(v.views), 0)::bigint from public.page_views_daily v where v.day = d::date),
           (select coalesce(sum(v.visits), 0)::bigint from public.page_views_daily v where v.day = d::date)
      from generate_series(current_date - (least(greatest(p_days, 1), 365) - 1), current_date, interval '1 day') d
     order by 1;
end;
$$;

create or replace function public.admin_top_pages(p_days int default 30)
returns table (page text, views bigint, visits bigint)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden';
  end if;
  return query
    select v.page, sum(v.views)::bigint, sum(v.visits)::bigint from public.page_views_daily v
     where v.day > current_date - least(greatest(p_days, 1), 365)
     group by v.page order by 2 desc limit 20;
end;
$$;

create or replace function public.admin_langs(p_days int default 30)
returns table (lang text, visits bigint)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden';
  end if;
  return query
    select v.lang, sum(v.visits)::bigint from public.page_views_daily v
     where v.day > current_date - least(greatest(p_days, 1), 365)
     group by v.lang order by 2 desc;
end;
$$;

-- Accounts: search by handle / name / e-mail, sorted by 'recent' (created), 'active' or 'games'.
create or replace function public.admin_users(p_query text default '', p_sort text default 'recent', p_limit int default 50)
returns table (id uuid, handle text, display_name text, email text, home_city text, created_at timestamptz,
               last_sign_in_at timestamptz, last_active date, active_days bigint, is_admin boolean, is_public boolean,
               is_suspended boolean, suspended_reason text, games bigint, tournaments bigint, reports_against bigint)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden';
  end if;
  return query
    with base as (
      select p.id, p.handle, p.display_name, u.email::text as email, p.home_city, p.created_at, u.last_sign_in_at,
             (select max(a.day) from public.active_days a where a.user_id = p.id) as last_active,
             (select count(*) from public.active_days a where a.user_id = p.id) as active_days,
             p.is_admin, p.is_public, p.is_suspended, p.suspended_reason,
             (select count(*) from public.game_results r where r.player_id = p.id)
               + (select count(*) from public.matches m where p.id in (m.player_a_id, m.player_b_id)) as games,
             (select count(*) from public.registrations g where g.user_id = p.id) as tournaments,
             (select count(*) from public.reports r where r.target_id = p.id::text
                 or r.target_id in (select s.id::text from public.swap_posts s where s.user_id = p.id)
                 or r.target_id in (select c.id::text from public.challenge_entries c where c.user_id = p.id)) as reports_against
        from public.profiles p
        left join auth.users u on u.id = p.id
       where coalesce(p_query, '') = ''
          or p.handle ilike '%' || p_query || '%'
          or p.display_name ilike '%' || p_query || '%'
          or u.email ilike '%' || p_query || '%'
    )
    select * from base
     order by case when p_sort = 'active' then coalesce(base.last_active, '1900-01-01'::date) end desc nulls last,
              case when p_sort = 'games' then base.games end desc nulls last,
              case when p_sort = 'reports' then base.reports_against end desc nulls last,
              base.created_at desc
     limit least(greatest(p_limit, 1), 500);
end;
$$;

-- Latest events across the site, for the activity feed.
create or replace function public.admin_recent(p_limit int default 40)
returns table (at timestamptz, kind text, label text, handle text, link text)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden';
  end if;
  return query
    select * from (
      select p.created_at, 'signup'::text, p.display_name, p.handle, '/u/' || p.handle from public.profiles p
      union all
      select g.created_at, 'game', g.game_system || ' - ' || g.city, p.handle, '/play/game/' || g.id from public.games g join public.profiles p on p.id = g.host_id
      union all
      select t.created_at, 'tournament', t.name, p.handle, '/play/t/' || t.slug from public.tournaments t join public.profiles p on p.id = t.organiser_id
      union all
      select l.created_at, 'league', l.name, p.handle, '/play/league/' || l.id from public.leagues l join public.profiles p on p.id = l.organiser_id
      union all
      select s.created_at, 'swap', s.title, p.handle, '/play/swap' from public.swap_posts s join public.profiles p on p.id = s.user_id
      union all
      select c.created_at, 'challenge', c.title, p.handle, '/paint/challenges' from public.challenge_entries c join public.profiles p on p.id = c.user_id
      union all
      select r.created_at, 'report', r.target_type::text || ': ' || r.reason, p.handle, null from public.reports r join public.profiles p on p.id = r.reporter_id
      union all
      select b.created_at, 'bug', left(b.message, 80), p.handle, '/admin/bugs' from public.bug_reports b left join public.profiles p on p.id = b.user_id
    ) x
    order by 1 desc
    limit least(greatest(p_limit, 1), 200);
end;
$$;

-- Moderation queue: reports with what they point at.
create or replace function public.admin_reports(p_status text default 'open')
returns table (id uuid, created_at timestamptz, status text, target_type text, target_id text, reason text,
               reporter_handle text, target_label text, owner_id uuid, owner_handle text, target_hidden boolean, same_target bigint)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden';
  end if;
  return query
    select r.id, r.created_at, r.status::text, r.target_type::text, r.target_id, r.reason, rp.handle,
           case r.target_type::text
             when 'swap' then (select s.title from public.swap_posts s where s.id::text = r.target_id)
             when 'challenge' then (select c.title from public.challenge_entries c where c.id::text = r.target_id)
             when 'entry' then (select e.title from public.contest_entries e where e.id::text = r.target_id)
             when 'profile' then (select p.display_name from public.profiles p where p.id::text = r.target_id)
             when 'photo' then (select gi.title from public.gallery_items gi where gi.id::text = r.target_id)
             else r.target_id end,
           o.id, o.handle,
           case r.target_type::text
             when 'swap' then (select s.is_hidden from public.swap_posts s where s.id::text = r.target_id)
             when 'challenge' then (select c.is_hidden from public.challenge_entries c where c.id::text = r.target_id)
             when 'entry' then (select e.is_hidden from public.contest_entries e where e.id::text = r.target_id)
             when 'profile' then (select not p.is_public from public.profiles p where p.id::text = r.target_id)
             when 'photo' then (select not gi.is_public from public.gallery_items gi where gi.id::text = r.target_id)
             else null end,
           (select count(*) from public.reports x where x.target_type = r.target_type and x.target_id = r.target_id)
      from public.reports r
      join public.profiles rp on rp.id = r.reporter_id
      left join public.profiles o on o.id = case r.target_type::text
             when 'swap' then (select s.user_id from public.swap_posts s where s.id::text = r.target_id)
             when 'challenge' then (select c.user_id from public.challenge_entries c where c.id::text = r.target_id)
             when 'entry' then (select e.user_id from public.contest_entries e where e.id::text = r.target_id)
             when 'profile' then r.target_id::uuid
             when 'photo' then (select gi.owner_id from public.gallery_items gi where gi.id::text = r.target_id)
             else null end
     where p_status = 'all' or r.status::text = p_status
     order by r.created_at desc
     limit 200;
end;
$$;

-- Content lists for direct moderation (latest first): swaps, challenge entries, tournaments, games.
create or replace function public.admin_content(p_type text, p_limit int default 50)
returns table (id text, created_at timestamptz, label text, owner_handle text, hidden boolean, link text)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden';
  end if;
  if p_type = 'swap' then
    return query select s.id::text, s.created_at, s.title, p.handle, s.is_hidden, '/play/swap'::text
      from public.swap_posts s join public.profiles p on p.id = s.user_id order by s.created_at desc limit p_limit;
  elsif p_type = 'challenge' then
    return query select c.id::text, c.created_at, c.title, p.handle, c.is_hidden, '/paint/challenges'::text
      from public.challenge_entries c join public.profiles p on p.id = c.user_id order by c.created_at desc limit p_limit;
  elsif p_type = 'tournament' then
    return query select t.id::text, t.created_at, t.name, p.handle, t.is_hidden, '/play/t/' || t.slug
      from public.tournaments t join public.profiles p on p.id = t.organiser_id order by t.created_at desc limit p_limit;
  elsif p_type = 'game' then
    return query select g.id::text, g.created_at, g.game_system || ' - ' || g.city, p.handle, g.status = 'cancelled', '/play/game/' || g.id
      from public.games g join public.profiles p on p.id = g.host_id order by g.created_at desc limit p_limit;
  elsif p_type = 'lfg' then
    return query select l.id::text, l.created_at, l.game_system, p.handle, not l.is_open, '/play/quick?view=lfg'::text
      from public.lfg_posts l join public.profiles p on p.id = l.author_id order by l.created_at desc limit p_limit;
  else
    raise exception 'bad_type';
  end if;
end;
$$;

-- ---------------------------------------------------------------------------------------------
-- Admin actions
-- ---------------------------------------------------------------------------------------------
create or replace function public.admin_set_report(p_id uuid, p_status text)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden';
  end if;
  update public.reports set status = p_status::public.report_status where id = p_id;
end;
$$;

-- Hide (true) or restore (false) a piece of content. Profiles and gallery photos are made private.
create or replace function public.admin_moderate(p_type text, p_id text, p_hidden boolean)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden';
  end if;
  case p_type
    when 'swap' then update public.swap_posts set is_hidden = p_hidden where id::text = p_id;
    when 'challenge' then update public.challenge_entries set is_hidden = p_hidden where id::text = p_id;
    when 'entry' then update public.contest_entries set is_hidden = p_hidden where id::text = p_id;
    when 'tournament' then update public.tournaments set is_hidden = p_hidden where id::text = p_id;
    when 'game' then update public.games set status = case when p_hidden then 'cancelled' else 'open' end::public.game_status where id::text = p_id;
    when 'lfg' then update public.lfg_posts set is_open = not p_hidden where id::text = p_id;
    when 'profile' then update public.profiles set is_public = not p_hidden where id::text = p_id;
    when 'photo' then update public.gallery_items set is_public = not p_hidden where id::text = p_id;
    else raise exception 'bad_type';
  end case;
end;
$$;

-- Suspend: blocks new posts, hides public content, closes open swap posts. Lifting it only clears
-- the flag (content stays hidden until restored one by one).
create or replace function public.admin_suspend(p_user uuid, p_suspended boolean, p_reason text default null)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden';
  end if;
  if p_user = auth.uid() then
    raise exception 'own_account';
  end if;
  update public.profiles
     set is_suspended = p_suspended,
         suspended_reason = case when p_suspended then left(btrim(coalesce(p_reason, '')), 300) end,
         is_public = case when p_suspended then false else is_public end
   where id = p_user;
  if p_suspended then
    update public.swap_posts set is_hidden = true where user_id = p_user;
    update public.challenge_entries set is_hidden = true where user_id = p_user;
    update public.contest_entries set is_hidden = true where user_id = p_user;
    update public.lfg_posts set is_open = false where author_id = p_user;
    update public.gallery_items set is_public = false where owner_id = p_user;
  end if;
end;
$$;

